-- =============================================================================
-- CARGA INICIAL TECNI-REPUESTOS
-- Genera: unidades_medidas, productos, stock_productos, movimientos_inventario
--
-- REQUISITOS PREVIOS:
--   * Esquema base ya creado (sql/controlbodega.sql)
--   * Existe al menos 1 bodega y 1 user (id_bodega y id_user abajo)
--
-- AJUSTAR si fuera necesario:
--   * v_id_bodega : bodega destino donde se registra el stock inicial
--   * v_id_user   : usuario que firma los movimientos
-- =============================================================================

BEGIN;

DO $$
DECLARE
    v_id_bodega INT := 1;
    v_id_user   INT := 1;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM bodegas WHERE id = v_id_bodega) THEN
        RAISE EXCEPTION 'No existe bodega id=%. Crea la bodega antes de correr esta carga.', v_id_bodega;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM users WHERE id = v_id_user) THEN
        RAISE EXCEPTION 'No existe user id=%. Crea el usuario antes de correr esta carga.', v_id_user;
    END IF;
END $$;

-- -----------------------------------------------------------------------------
-- 1. UNIDADES DE MEDIDA (idempotente)
-- -----------------------------------------------------------------------------

-- -----------------------------------------------------------------------------
-- 2. STAGING: tabla temporal con todo el catálogo
-- -----------------------------------------------------------------------------
CREATE TEMP TABLE _carga_tecni (
    codigo         varchar PRIMARY KEY,
    descripcion    varchar,
    unidad         varchar,
    precio_costo   double precision,
    precio_venta1  double precision,
    precio_venta2  double precision,
    precio_venta3  double precision,
    cantidad       double precision
) ON COMMIT DROP;









-- -----------------------------------------------------------------------------
-- 3. PRODUCTOS (insert nuevos, idempotente por codigo_barras)
-- -----------------------------------------------------------------------------
    codigo_barras, descripcion, id_unidad,
    precio_costo, precio_venta, precio_venta2, precio_venta3,
    estado, tipo, stock_minimo, stock_ideal, cant_paquete
)
SELECT
    c.codigo,
    c.descripcion,
    u.id,
    COALESCE(c.precio_costo, 0),
    COALESCE(c.precio_venta1, 0),
    COALESCE(c.precio_venta2, 0),
    COALESCE(c.precio_venta3, 0),
    TRUE,
    0,
    0,
    0,
    1
FROM _carga_tecni c
JOIN unidades_medidas u ON u.nombre = c.unidad
WHERE NOT EXISTS (
    SELECT 1 FROM productos p WHERE p.codigo_barras = c.codigo
);

-- -----------------------------------------------------------------------------
-- 4. STOCK_PRODUCTOS (todas las filas, incluso con cantidad 0 o negativa)
-- -----------------------------------------------------------------------------
DO $$
DECLARE
    v_id_bodega INT := 1;
BEGIN
    SELECT
        p.id,
        v_id_bodega,
        c.cantidad,
        0,
        COALESCE(c.precio_costo, 0)
    FROM _carga_tecni c
    JOIN productos p ON p.codigo_barras = c.codigo
    WHERE NOT EXISTS (
        SELECT 1 FROM stock_productos sp
        WHERE sp.id_producto = p.id AND sp.id_bodega = v_id_bodega
    );
END $$;

-- -----------------------------------------------------------------------------
-- 5. MOVIMIENTOS DE INVENTARIO  (carga inicial)
--    Positivos -> tipo='INGRESO' afecta_cantidad=+1
--    Negativos -> tipo='AJUSTE_NEGATIVO' afecta_cantidad=-1, valor=abs()
--    Cero      -> sin movimiento
-- -----------------------------------------------------------------------------
DO $$
DECLARE
    v_id_bodega INT := 1;
    v_id_user   INT := 1;
    v_hora      VARCHAR(8) := to_char(now(), 'HH24:MI:SS');
BEGIN
    -- INGRESO inicial (cantidad > 0)
        id_producto, id_bodega, id_user,
        tipo, afecta_cantidad, afecta_pendientes, valor,
        valor_anterior, valor_nuevo,
        costo_unitario, costo_promedio_anterior, costo_promedio_nuevo,
        cantidad_anterior, cantidad_nueva, pendientes_anterior, pendientes_nuevo,
        id_referencia, tabla_referencia,
        fecha, hora, observacion
    )
    SELECT
        p.id, v_id_bodega, v_id_user,
        'INGRESO', 1, 0, c.cantidad,
        NULL, NULL,
        COALESCE(c.precio_costo, 0), 0, COALESCE(c.precio_costo, 0),
        0, c.cantidad, 0, 0,
        NULL, 'CARGA_INICIAL',
        ('now'::text)::date, v_hora, 'Carga inicial desde Excel (cantidad y venta)'
    FROM _carga_tecni c
    JOIN productos p ON p.codigo_barras = c.codigo
    WHERE c.cantidad > 0;

    -- AJUSTE_NEGATIVO inicial (cantidad < 0)
        id_producto, id_bodega, id_user,
        tipo, afecta_cantidad, afecta_pendientes, valor,
        valor_anterior, valor_nuevo,
        costo_unitario, costo_promedio_anterior, costo_promedio_nuevo,
        cantidad_anterior, cantidad_nueva, pendientes_anterior, pendientes_nuevo,
        id_referencia, tabla_referencia,
        fecha, hora, observacion
    )
    SELECT
        p.id, v_id_bodega, v_id_user,
        'AJUSTE_NEGATIVO', -1, 0, abs(c.cantidad),
        NULL, NULL,
        COALESCE(c.precio_costo, 0), 0, COALESCE(c.precio_costo, 0),
        0, c.cantidad, 0, 0,
        NULL, 'CARGA_INICIAL',
        ('now'::text)::date, v_hora, 'Carga inicial desde Excel - existencia negativa heredada'
    FROM _carga_tecni c
    JOIN productos p ON p.codigo_barras = c.codigo
    WHERE c.cantidad < 0;
END $$;

-- -----------------------------------------------------------------------------
-- 6. RESUMEN
-- -----------------------------------------------------------------------------
DO $$
DECLARE
    v_id_bodega INT := 1;
    v_total_prod INT;
    v_total_stock INT;
    v_total_mov INT;
    v_neg INT;
BEGIN
    SELECT COUNT(*) INTO v_total_prod FROM productos;
    SELECT COUNT(*) INTO v_total_stock FROM stock_productos WHERE id_bodega = v_id_bodega;
    SELECT COUNT(*) INTO v_total_mov FROM movimientos_inventario WHERE tabla_referencia = 'CARGA_INICIAL';
    SELECT COUNT(*) INTO v_neg FROM stock_productos WHERE id_bodega = v_id_bodega AND cantidad < 0;
    RAISE NOTICE 'Productos en BD : %', v_total_prod;
    RAISE NOTICE 'Filas stock     : %', v_total_stock;
    RAISE NOTICE 'Movimientos     : %', v_total_mov;
    RAISE NOTICE 'Stock negativo  : %', v_neg;
END $$;

COMMIT;
